// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId,
	waitForRoute
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-refinements');
const BSBM_INSTANCES = 'http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/instances/';

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

async function openExplore(page, iri) {
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'explore') + '?resource=' + encodeURIComponent('<' + iri + '>'),
		{ waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'explore');
	await page.locator('#explore-resource-card').waitFor({ state: 'visible' });
}

test('the explored resource card keeps its actions on one row', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	await openExplore(page, BSBM_INSTANCES + 'ProductType2');
	const query = page.locator('#explore-resource-card .explore-resource-card__query');
	const add = page.locator('#explore-resource-card .workbench-add-to-graph');
	await expect(query).toBeVisible();
	await expect(add).toBeVisible();
	const [queryBox, addBox] = [await query.boundingBox(), await add.boundingBox()];
	expect(Math.round(queryBox.y), 'both actions start on the same row').toBe(Math.round(addBox.y));
	expect(addBox.x, 'Add to graph follows Query this resource').toBeGreaterThan(queryBox.x + queryBox.width);
});

test('the query editor toolbar controls take keyboard focus with the focus ring', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'query');
	const fullscreen = page.locator('#query-page .yasqe_fullscreenBtn');
	await expect(fullscreen).toHaveAttribute('role', 'button');
	await expect(fullscreen).toHaveAccessibleName('Full screen');
	await page.locator('#query-editor-resize').focus();
	await page.keyboard.press('Shift+Tab');
	await expect(fullscreen).toBeFocused();
	const outline = await fullscreen.evaluate((element) => {
		const style = getComputedStyle(element);
		return { style: style.outlineStyle, width: style.outlineWidth };
	});
	expect(outline).toEqual({ style: 'solid', width: '2px' });
	await page.keyboard.press('Enter');
	await expect(page.locator('#query-page .yasqe .CodeMirror-fullscreen')).toBeVisible();
	await page.locator('#query-page .yasqe_smallscreenBtn').press('Enter');
	await expect(page.locator('#query-page .yasqe .CodeMirror-fullscreen')).toHaveCount(0);
});

test('an Update syntax error points at its line like the Query page does', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'update'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'update');
	await page.locator('.CodeMirror').first().evaluate((element) => element.CodeMirror.setValue('DELETE WHERE {\n  ?s ?p\n}'));
	await page.locator('#update-form input[type="submit"]').click();
	const callout = page.locator('[id="updateString.errors"]');
	await expect(callout.locator('.workbench-callout__title')).toHaveText('Syntax error on line 3, column 1');
	await expect(callout.locator('.query-result-error__message')).toHaveText('Unexpected "}".');
	await expect(callout.locator('.query-result-error__details pre')).toContainText('Encountered');
	await callout.getByRole('button', { name: 'Go to line 3' }).click();
	const line = page.locator('#update-editor .CodeMirror-code > div').nth(2);
	await expect(line.locator('.query-editor-error-line')).toHaveCount(1);
	const colors = await page.evaluate(() => {
		const marked = document.querySelector('#update-editor .query-editor-error-line');
		const probe = document.createElement('div');
		probe.style.background = 'var(--workbench-danger-surface)';
		document.body.appendChild(probe);
		const expected = getComputedStyle(probe).backgroundColor;
		probe.remove();
		return { marked: getComputedStyle(marked).backgroundColor, expected };
	});
	expect(colors.marked, 'the reported line is tinted').toBe(colors.expected);
	expect(await page.locator('.CodeMirror').first().evaluate((element) => element.CodeMirror.getCursor().line)).toBe(2);
});

test('query form labels end without a colon, like every other label', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'query');
	await page.locator('#save-query-toggle').click();
	await expect(page.locator('label[for="query-name"]')).toBeVisible();
	const suffixes = await page.locator('.query-form__label').evaluateAll((labels) => labels
		.map((label) => [label.textContent.trim(), getComputedStyle(label, '::after').content])
		.filter(([, content]) => content !== 'none' && content !== '""' && content !== 'normal'));
	expect(suffixes).toEqual([]);
});

