test('copying the explored resource confirms on the button', async ({ page, context, browserName }) => {
	test.skip(browserName !== 'chromium', 'clipboard permissions are granted only in Chromium');
	await context.grantPermissions(['clipboard-read', 'clipboard-write']);
	await page.setViewportSize({ width: 1280, height: 900 });
	await openExplore(page, BSBM_INSTANCES + 'ProductType2');
	await page.getByRole('button', { name: 'Copy resource' }).click();
	const copied = page.locator('#explore-resource-card .explore-resource-card__iri button');
	await expect(copied).toHaveAttribute('aria-label', 'Copied');
	await expect(page.locator('#workbench-route-status')).toHaveText('Copied');
	expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(BSBM_INSTANCES + 'ProductType2');
	await expect(copied).toHaveAttribute('aria-label', 'Copy resource', { timeout: 5000 });
});

