test('the empty query editor shows an example until something is typed', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'query');
	await page.locator('#query-page .CodeMirror').first().evaluate((element) => element.CodeMirror.setValue(''));
	const hint = page.locator('#query-page .CodeMirror > .workbench-editor-hint');
	await expect(hint).toBeVisible();
	await expect(hint).toHaveText('Write a SPARQL query, for example: SELECT * WHERE { ?s ?p ?o } LIMIT 10');
	const [hintBox, line] = [await hint.boundingBox(), await page.locator('#query-page .CodeMirror-line').first().boundingBox()];
	expect(Math.abs(hintBox.x - line.x - 4), 'the hint starts where the first line\'s text starts').toBeLessThan(2);
	await page.locator('#query-page .CodeMirror').first().click();
	await page.keyboard.type('S');
	await expect(hint).toBeHidden();
});

