test('Information shows memory in use against the maximum, its share on one line on a phone', async ({ page }) => {
	await page.setViewportSize({ width: 375, height: 812 });
	await page.goto(repositoryPageUrl('NONE', 'information'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'information');
	const meter = page.locator('#information-memory meter.workbench-memory-meter');
	await expect(meter).toHaveAccessibleName('Memory used of the maximum');
	const share = page.locator('#information-memory .workbench-memory-share');
	// A small server's share reads "less than 1%", the longest form, rather than a misleading 0%.
	await expect(share).toHaveText(/^(\d+%|less than 1%|more than 99%) of the maximum$/);
	// One line: every box of the text has the same top (a run may still be split into several boxes on that line).
	const lines = await share.evaluate((element) => new Set(Array.from(element.getClientRects(), (rect) => Math.round(rect.top))).size);
	expect(lines, 'the share does not break mid-phrase').toBe(1);
});

test('the first Tab offers to skip the menu, and Enter moves to the page', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'summary'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'summary');
	const skip = page.locator('a.workbench-skip-link');
	await expect(skip).toHaveText('Skip to content');
	await expect(skip).not.toBeInViewport();
	await page.locator('body').focus();
	await page.keyboard.press('Tab');
	await expect(skip).toBeFocused();
	await expect(skip).toBeInViewport();
	const colors = await skip.evaluate((element) => {
		const style = getComputedStyle(element);
		return { text: style.color, background: style.backgroundColor };
	});
	expect(colors.text, 'its text stands out from its background').not.toBe(colors.background);
	await page.keyboard.press('Enter');
	await expect(page.locator('#title_heading')).toBeFocused();
	expect(new URL(page.url()).pathname, 'skipping does not navigate').toMatch(/\/summary$/);
	await page.keyboard.press('Tab');
	await expect(page.locator('#workbench-navigation-disclosure a').first(), 'the next Tab is in the page, not the menu')
		.not.toBeFocused();
});

test('Explore heads a multilingual resource with the label in the browser\'s language', async ({ browser, request }) => {
	const loaded = await request.post(`${serverBaseUrl()}/repositories/${encodeURIComponent(REPOSITORY_ID)}/statements`, {
		headers: { 'Content-Type': 'application/n-triples' },
		data: ['"Chat"@fr', '"Cat"@en', '"Katze"@de'].map((label) =>
			`<urn:refinements:cat> <http://www.w3.org/2000/01/rdf-schema#label> ${label} .`).join('\n')
	});
	expect([200, 204]).toContain(loaded.status());
	const context = await browser.newContext({ locale: 'de-DE', viewport: { width: 1280, height: 900 } });
	const page = await context.newPage();
	try {
		await page.goto(repositoryPageUrl(REPOSITORY_ID, 'explore') + '?resource=' + encodeURIComponent('<urn:refinements:cat>'),
			{ waitUntil: 'domcontentloaded' });
		await waitForRoute(page, 'explore');
		await expect(page.locator('#explore-resource-card h2')).toHaveText('Katze');
	} finally {
		await context.close();
	}
});
